CREATE TABLE truss.module_access (document_id text NOT NULL COLLATE pg_catalog."C", module text NOT NULL COLLATE pg_catalog."C", reader_role text NOT NULL COLLATE pg_catalog."C", writer_role text NOT NULL COLLATE pg_catalog."C", CONSTRAINT module_access_qualified_pk PRIMARY KEY (document_id, module), CONSTRAINT module_access_roles_differ CHECK (reader_role <> writer_role)); CREATE TABLE truss.type_def (document_id text NOT NULL COLLATE pg_catalog."C", type_id int PRIMARY KEY, module text NOT NULL COLLATE pg_catalog."C", element text NOT NULL COLLATE pg_catalog."C", kind text NOT NULL, provisional boolean NOT NULL DEFAULT false, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int, retired_rev int REFERENCES truss.schema_rev (rev), lineage_profile text NOT NULL COLLATE pg_catalog."C", lineage_bytes bytea NOT NULL, lineage_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(lineage_bytes)) STORED, CONSTRAINT type_def_lineage_profile_nonempty CHECK (octet_length(lineage_profile) > 0), CONSTRAINT type_def_lineage_bytes_nonempty CHECK (octet_length(lineage_bytes) > 0), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.rel_def (document_id text NOT NULL COLLATE pg_catalog."C", rel_type_id int PRIMARY KEY, module text NOT NULL COLLATE pg_catalog."C", rel_id text NOT NULL COLLATE pg_catalog."C", name text NOT NULL, source_min int NOT NULL, source_max int, target_min int NOT NULL, target_max int, lifecycle text NOT NULL, directed boolean NOT NULL, target_key text, composition boolean NOT NULL DEFAULT false, assoc_type_id int REFERENCES truss.type_def (type_id), inverse text, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int NOT NULL, retired_rev int REFERENCES truss.schema_rev (rev), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE INDEX type_def_lineage_route ON truss.type_def USING btree (lineage_sha256, type_id)